recipes.code:
{
  "inputs": [
    {
      "id": "monnet-api-key",
      "type": "promptString",
      "description": "Your Monnet API key (mnk_...). Generate one at https://app.monnet.ai/settings (API Keys tab).",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@monnet/mcp@0.2.3"
      ],
      "env": {
        "MONNET_API_KEY": "${input:monnet-api-key}"
      }
    }
  }
}
